import re

from auto_config.generator.section_generic import SectionGeneric
from auto_config.generator.utils.logger import logger
from auto_config.generator.utils.utils import flatten_list_if_single_element
from auto_config.generator.utils.utils import is_type_sa, is_type_sa_nsa, get_env
from copy import deepcopy


class ManagedObjectGeneric(SectionGeneric):

    def __init__(self, dist_name, mo_params, enb_ent_config, pddb_topology, pddb_parser):
        super().__init__()
        self.dist_name = dist_name
        self.mo_params = mo_params
        self.reference_mo_params = deepcopy(mo_params)
        self.enb_ent_config = enb_ent_config
        self.pddb_topology = pddb_topology
        self.pddb_parser = pddb_parser
        self.fail_on_error = get_env("AC_FAIL_ON_ERROR")
        self.debug = get_env("AC_DEBUG")

    @property
    def mo(self):
        mo = self.dist_name.split('/')[-1] if '/' in self.dist_name else self.dist_name
        return mo

    @property
    def mo_name(self):
        mo = self.dist_name.split('/')[-1] if '/' in self.dist_name else self.dist_name
        return mo.split('-')[0]

    @property
    def mo_num(self):
        mo = self.dist_name.split('/')[-1] if '/' in self.dist_name else self.dist_name
        return mo.split('-')[1]

    @property
    def cell_num(self):
        cell_match = re.search(r'/(?:LNCEL|LCELL|NRCELL|NRCELL_FDD|NRCELLGRP|LCELNR)-(\d+)', self.dist_name)
        cell_num = cell_match.group(1) if cell_match else None
        return cell_num

    @property
    def is_sa_nsa(self):
        return is_type_sa_nsa(self.enb_ent_config)

    @property
    def is_sa(self):
        return is_type_sa(self.enb_ent_config)

    def is_ecpri_72a(self, radio_mo_num):
        try:
            if self.enb_ent_config['radios'][radio_mo_num]['protocol_version'] == '72a':
                return True
        except Exception:
            pass
        return False

    @staticmethod
    def get_len_str(val):
        return str(len(val))

    @property
    def radio_num(self):
        return re.search(r'RMOD-(\d+)', self.dist_name).group(1) if 'RMOD-' in self.dist_name else None

    def _prepare_section_content(self, *args, **kwargs):
        return self.mo_params

    def set_parameter(self, parameter_name, parameter_value):
        try:
            if parameter_name not in self.mo_params:
                logger.warning(f"'Parameter {parameter_name} not found in {self.dist_name}")
                return
            self.mo_params[parameter_name]['required'] = True
            self.mo_params[parameter_name]['default'] = parameter_value
            logger.debug(f"{'Setting':15}{parameter_name:30} = {str(parameter_value):40} in {self.dist_name}")
            self.pddb_parser.check_range(f"{self.mo_name}::{parameter_name}", self.mo_params[parameter_name])
        except Exception as exc:
            self.error(f"{exc}")

    def set_struct_parameter(self, struct_parameter_name, subparameter_name, subparameter_value=None):
        """
        e.g.:
        <list name="l2VlanIdList">
            <item>
                <p name="highValue">4094</p>
                <p name="lowValue">2</p>
            </item>
        </list>
        """
        try:
            if struct_parameter_name not in self.mo_params:
                logger.warning(f"'Struct parameter {struct_parameter_name} not found in {self.dist_name}")
                return
            self.mo_params[struct_parameter_name]['required'] = True
            if isinstance(subparameter_name, list):
                return self.set_struct_parameter_list(struct_parameter_name, subparameter_name)
            self.mo_params[struct_parameter_name]['struct'][subparameter_name]['required'] = True
            self.mo_params[struct_parameter_name]['struct'][subparameter_name]['default'] = subparameter_value
            logger.debug(f"{'Setting':15}{subparameter_name:30} = {str(subparameter_value):40} in {self.dist_name}")
            self.pddb_parser.check_range(f"{self.mo_name}::{struct_parameter_name}::{subparameter_name}",
                                         self.mo_params[struct_parameter_name]['struct'][subparameter_name])
        except Exception as exc:
            self.error(f"{exc}")

    def set_struct_parameter_list(self, struct_parameter_name, subparameter_list):
        self.add_required_struct_parameters(struct_parameter_name, subparameter_list)
        for subparameter_dict in subparameter_list:
            if isinstance(subparameter_dict, dict):
                for subparameter_name, subparameter_value in subparameter_dict.items():
                    if subparameter_name not in self.mo_params[struct_parameter_name]['struct']:
                        logger.warning(f"'Subparameter {subparameter_name} not found in {struct_parameter_name}")
                        continue
                    self.mo_params[struct_parameter_name]['struct'][subparameter_name]['required'] = True
                    if isinstance(self.mo_params[struct_parameter_name]['struct'][subparameter_name]['default'], list):
                        self.mo_params[struct_parameter_name]['struct'][subparameter_name]['default'].append(subparameter_value)
                    else:
                        self.mo_params[struct_parameter_name]['struct'][subparameter_name]['default'] = [subparameter_value]
                    logger.debug(f"{'Setting':15}{subparameter_name:30} = {str(subparameter_value):40} in {self.dist_name}")
                    self.pddb_parser.check_range(f"{self.mo_name}::{struct_parameter_name}::{subparameter_name}",
                                                 self.mo_params[struct_parameter_name]['struct'][subparameter_name])
            else:
                self.mo_params[struct_parameter_name]['default'] = subparameter_list
                self.pddb_parser.check_range(f"{self.mo_name}::{struct_parameter_name}",
                                             self.mo_params[struct_parameter_name])

    def add_required_struct_parameters(self, struct_parameter_name, subparameter_list):
        if 'struct' in self.mo_params[struct_parameter_name]:
            for subparameter_name in self.mo_params[struct_parameter_name]['struct']:
                if self.mo_params[struct_parameter_name]['struct'][subparameter_name]['required'] is True:
                    for subparameter_dict in subparameter_list:
                        if subparameter_name in subparameter_dict:
                            continue
                        subparameter_dict[subparameter_name] = self.mo_params[struct_parameter_name]['struct'][subparameter_name]['default']

    def drop_parameter(self, parameter_name, force=False):
        try:
            if not force and self.reference_mo_params[parameter_name]['required']:
                logger.debug(f"{'Cannot Drop':15}{parameter_name:73} in {self.dist_name}. It is required by PDDB")
            else:
                self.mo_params[parameter_name]['required'] = False
                logger.debug(f"{'Dropping':15}{parameter_name:73} in {self.dist_name}")
        except KeyError:
            logger.debug(f"{'Parameter':15}{parameter_name:30}   {'was not found':40} in {self.dist_name}")

    def generate_section_content(self, *args, **kwargs):
        """
        This function converts Managed Objects params dictionary into dictionary with proper format for XML dumping
        """
        self._prepare_section_content(*args, **kwargs)
        params_xml_formatted = {}

        self._set_mo_index_not_visible()
        list_parameters, simple_parameters = [], []

        for parameter_name, parameter_values in filter(lambda p: p[1]['required'], self.mo_params.items()):

            if 'struct' in parameter_values:
                self.fetch_struct_parameters(list_parameters, parameter_name, parameter_values)
            else:
                self.fetch_simple_parameters(simple_parameters, list_parameters, parameter_name, parameter_values)

        if list_parameters:
            list_parameters = flatten_list_if_single_element(list_parameters)
            params_xml_formatted['list'] = list_parameters

        if simple_parameters:
            simple_parameters = flatten_list_if_single_element(simple_parameters)
            params_xml_formatted['p'] = simple_parameters

        return params_xml_formatted

    def fetch_struct_parameters(self, list_parameters, parameter_name, parameter_values):
        if parameter_values['required'] and not isinstance(parameter_values['default'], tuple):
            struct_parameter_values = []
            struct_list_parameter_items = {}
            for subparameter_name, subparameter_values in parameter_values['struct'].items():
                if subparameter_values['required'] and isinstance(subparameter_values['default'], list):
                    for index, subparameter_value in enumerate(subparameter_values['default']):
                        if index not in struct_list_parameter_items:
                            struct_list_parameter_items[index] = {}
                        struct_list_parameter_items[index][subparameter_name] = str(subparameter_value)
                elif subparameter_values['required'] and subparameter_values['default'] is not None:
                    struct_parameter_values.append({
                        '#text': str(subparameter_values['default']),
                        '@name': subparameter_name,
                    })

            if struct_list_parameter_items:
                self.fetch_struct_parameters_add_list_items(list_parameters, parameter_name, struct_list_parameter_items)
            elif struct_parameter_values:
                self.fetch_struct_parameters_add_list_values(list_parameters, parameter_name, struct_parameter_values)

    def fetch_struct_parameters_add_list_items(self, list_parameters, parameter_name, struct_list_parameter_items):
        struct_parameter = {'@name': parameter_name}
        struct_parameter_items = []
        for index in sorted(struct_list_parameter_items):
            p_items = []
            for subparameter_name in sorted(struct_list_parameter_items[index]):
                p_items.append({
                    '#text': struct_list_parameter_items[index][subparameter_name],
                    '@name': subparameter_name,
                })
            struct_parameter_items.append({'p': p_items})
        struct_parameter['item'] = struct_parameter_items
        list_parameters.append(struct_parameter)

    def fetch_struct_parameters_add_list_values(self, list_parameters, parameter_name, struct_parameter_values):
        struct_parameter = {'@name': parameter_name}
        struct_parameter_values = flatten_list_if_single_element(struct_parameter_values)
        struct_parameter['item'] = {'p': struct_parameter_values}
        list_parameters.append(struct_parameter)

    def fetch_simple_parameters(self, simple_parameters, list_parameters, parameter_name, parameter_values):
        if isinstance(parameter_values['default'], tuple):
            no_text_struct_parameter = {
                '@name': parameter_name,
                'p': [str(x) for x in parameter_values['default']]
            }
            list_parameters.append(no_text_struct_parameter)

        elif isinstance(parameter_values['default'], list):
            no_text_struct_parameter = {
                '@name': parameter_name,
                'p': [str(x) for x in parameter_values['default']]
            }
            list_parameters.append(no_text_struct_parameter)

        elif parameter_values['default'] is not None:
            count = int(parameter_values['count'])
            if count > 1:
                no_text_struct_parameter = {
                    '@name': parameter_name,
                    'p': [str(parameter_values['default'])]
                }
                list_parameters.append(no_text_struct_parameter)
            else:
                parameter = {
                    '@name': parameter_name,
                    '#text': str(parameter_values['default'])
                }
                simple_parameters.append(parameter)

    def _set_mo_index_not_visible(self):
        try:
            index_name = self.pddb_topology[self.mo_name]['index']
            self.mo_params[index_name]['required'] = False
        except Exception as exc:
            raise IndexError("Index or parameter not found in PDDB topology for {} ({}).".format(self.mo_name, exc))

    def error(self, msg):
        logger.error(msg)
        if self.fail_on_error:
            raise Exception(msg)

    def log(self, msg):
        if self.debug:
            logger.info(msg)
